package com.lmspilot.operations.api;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.lmspilot.operations.domain.*;import com.lmspilot.support.api.ApiException;import com.lmspilot.support.security.CurrentUser;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.client.RestClient;import java.time.*;import java.util.*;
@Service public class OperationsService{private final OperationJobRepository jobs;private final OperationScheduleRepository schedules;private final ObjectMapper mapper;private final Duration lease;private final Map<String,String> urls;public OperationsService(OperationJobRepository j,OperationScheduleRepository s,ObjectMapper m,@Value("${operations.service-urls:}")String raw,@Value("${operations.agent-lease:PT2M}")Duration l){jobs=j;schedules=s;mapper=m;lease=l;Map<String,String>x=new LinkedHashMap<>();for(String e:raw.split(",")){String[]p=e.split("=",2);if(p.length==2)x.put(p[0],p[1]);}urls=Map.copyOf(x);}
 public List<ServiceHealth> health(){List<ServiceHealth>r=new ArrayList<>();urls.forEach((n,u)->{try{Map<?,?>b=RestClient.create().get().uri(u+"/actuator/health").retrieve().body(Map.class);Map<String,Object>d=new LinkedHashMap<>();if(b!=null)b.forEach((k,v)->d.put(String.valueOf(k),v));r.add(new ServiceHealth(n,b==null||b.get("status")==null?"UNKNOWN":String.valueOf(b.get("status")),null,d));}catch(Exception e){r.add(new ServiceHealth(n,"DOWN",null,Map.of("error",e.getMessage()==null?"unavailable":e.getMessage())));}});return r;}
 @Transactional(readOnly=true) public List<OperationJobResponse> jobs(){return jobs.findAllByOrderByRequestedAtDesc().stream().map(this::response).toList();}@Transactional public OperationJobResponse request(OperationType t,OperationRequest i){validate(t,i.parameters());return response(jobs.save(new OperationJobEntity(t,CurrentUser.id(),write(i.parameters()))));}
 @Transactional public AgentClaimResponse claim(String agentId){var j=jobs.lockNextClaimable();if(j==null)return null;Instant n=Instant.now();j.setStatus(OperationStatus.RUNNING);if(j.getStartedAt()==null)j.setStartedAt(n);j.setClaimedBy(agentId.trim().substring(0,Math.min(160,agentId.trim().length())));j.setClaimToken(UUID.randomUUID().toString());j.setHeartbeatAt(n);j.setLeaseUntil(n.plus(lease));j.setAttemptCount(j.getAttemptCount()+1);return new AgentClaimResponse(j.getId(),j.getType(),read(j.getParametersJson()),j.getClaimToken(),j.getLeaseUntil(),j.getAttemptCount());}
 @Transactional public Instant heartbeat(UUID id,String token){var j=claimed(id,token);if(j.getStatus()!=OperationStatus.RUNNING)throw conflict("Job không còn ở trạng thái RUNNING");Instant n=Instant.now();j.setHeartbeatAt(n);j.setLeaseUntil(n.plus(lease));return j.getLeaseUntil();}@Transactional public OperationJobResponse complete(UUID id,AgentCompleteRequest i){var j=claimed(id,i.claimToken());if(j.getStatus()!=OperationStatus.RUNNING)throw conflict("Job không còn ở trạng thái RUNNING");j.setStatus(i.success()?OperationStatus.SUCCEEDED:OperationStatus.FAILED);j.setFinishedAt(Instant.now());j.setResultJson(write(i.result()));j.setErrorMessage(i.success()?null:String.valueOf(i.result().getOrDefault("error","Operation failed")));j.setLeaseUntil(null);return response(j);}
 @Transactional(readOnly=true)public List<OperationScheduleResponse>schedules(){return schedules.findAllByOrderByCreatedAtDesc().stream().map(this::scheduleResponse).toList();}@Transactional public OperationScheduleResponse createSchedule(OperationScheduleRequest i){validateSchedule(i);return scheduleResponse(schedules.save(new OperationScheduleEntity(i.name().trim(),i.operationType(),i.frequency(),i.dayOfWeek(),i.hourUtc(),write(i.parameters()),i.enabled(),nextRun(i.frequency(),i.dayOfWeek(),i.hourUtc(),Instant.now()),CurrentUser.id())));}@Transactional public OperationScheduleResponse updateSchedule(UUID id,OperationScheduleRequest i){validateSchedule(i);var e=schedules.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"OPERATION_SCHEDULE_NOT_FOUND","Không tìm thấy lịch vận hành"));e.setName(i.name().trim());e.setOperationType(i.operationType());e.setFrequency(i.frequency());e.setDayOfWeek(i.dayOfWeek());e.setHourUtc(i.hourUtc());e.setParametersJson(write(i.parameters()));e.setEnabled(i.enabled());e.setNextRunAt(nextRun(i.frequency(),i.dayOfWeek(),i.hourUtc(),Instant.now()));e.setUpdatedAt(Instant.now());return scheduleResponse(e);}@Transactional public void deleteSchedule(UUID id){if(!schedules.existsById(id))throw new ApiException(HttpStatus.NOT_FOUND,"OPERATION_SCHEDULE_NOT_FOUND","Không tìm thấy lịch vận hành");schedules.deleteById(id);}
 @Scheduled(fixedDelayString="${operations.schedule-worker-delay-ms:60000}")@Transactional public void runSchedules(){Instant n=Instant.now();for(var s:schedules.findTop50ByEnabledTrueAndNextRunAtBeforeOrderByNextRunAtAsc(n)){jobs.save(new OperationJobEntity(s.getOperationType(),s.getCreatedBy(),s.getParametersJson()));s.setNextRunAt(nextRun(s.getFrequency(),s.getDayOfWeek(),s.getHourUtc(),n.plusSeconds(60)));s.setUpdatedAt(n);}}
 private void validateSchedule(OperationScheduleRequest i){if(i.operationType()!=OperationType.BACKUP&&i.operationType()!=OperationType.MAINTENANCE)throw new ApiException(HttpStatus.BAD_REQUEST,"UNSAFE_SCHEDULE_TYPE","Chỉ cho phép lập lịch sao lưu hoặc chế độ bảo trì");if(i.frequency()==OperationScheduleFrequency.WEEKLY&&i.dayOfWeek()==null)throw new ApiException(HttpStatus.BAD_REQUEST,"SCHEDULE_DAY_REQUIRED","Lịch tuần cần ngày trong tuần");validate(i.operationType(),i.parameters());}private Instant nextRun(OperationScheduleFrequency f,Integer day,int hour,Instant from){ZonedDateTime n=ZonedDateTime.ofInstant(from,ZoneOffset.UTC).withMinute(0).withSecond(0).withNano(0).withHour(hour);if(!n.toInstant().isAfter(from))n=n.plusDays(1);if(f==OperationScheduleFrequency.WEEKLY){DayOfWeek t=DayOfWeek.of(day==null?1:day);while(n.getDayOfWeek()!=t)n=n.plusDays(1);}return n.toInstant();}
 private OperationJobEntity claimed(UUID id,String token){var j=jobs.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"JOB_NOT_FOUND","Không tìm thấy job"));if(j.getClaimToken()==null||j.getClaimToken().isBlank()||!j.getClaimToken().equals(token))throw new ApiException(HttpStatus.FORBIDDEN,"INVALID_CLAIM_TOKEN","Claim token không hợp lệ");return j;}private void validate(OperationType t,Map<String,String>p){if(t==OperationType.RESTORE){if(!"RESTORE".equals(p.get("confirmation")))throw new ApiException(HttpStatus.BAD_REQUEST,"RESTORE_CONFIRMATION_REQUIRED","Phục hồi yêu cầu confirmation=RESTORE");if(blank(p.get("backupPath")))throw new ApiException(HttpStatus.BAD_REQUEST,"BACKUP_PATH_REQUIRED","Phục hồi yêu cầu backupPath");}if(t==OperationType.MAINTENANCE&&!Set.of("ON","OFF").contains(String.valueOf(p.get("mode")).toUpperCase()))throw new ApiException(HttpStatus.BAD_REQUEST,"MAINTENANCE_MODE_REQUIRED","Chế độ bảo trì yêu cầu mode=ON hoặc OFF");if((t==OperationType.UPDATE||t==OperationType.ROLLBACK)&&blank(p.get("packagePath")))throw new ApiException(HttpStatus.BAD_REQUEST,"PACKAGE_PATH_REQUIRED","Cập nhật/rollback yêu cầu packagePath");}
 private boolean blank(String s){return s==null||s.isBlank();}private ApiException conflict(String m){return new ApiException(HttpStatus.CONFLICT,"OPERATION_STATE_CONFLICT",m);}private String write(Object v){try{return mapper.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException(e);}}private Map<String,String>read(String s){try{return mapper.readValue(s,new TypeReference<>(){});}catch(Exception e){throw new IllegalStateException(e);}}private OperationScheduleResponse scheduleResponse(OperationScheduleEntity e){return new OperationScheduleResponse(e.getId(),e.getName(),e.getOperationType(),e.getFrequency(),e.getDayOfWeek(),e.getHourUtc(),read(e.getParametersJson()),e.isEnabled(),e.getNextRunAt(),e.getCreatedBy(),e.getUpdatedAt());}private OperationJobResponse response(OperationJobEntity e){return new OperationJobResponse(e.getId(),e.getType(),e.getStatus(),e.getRequestedBy(),e.getRequestedAt(),e.getStartedAt(),e.getFinishedAt(),e.getResultJson(),e.getErrorMessage(),e.getClaimedBy(),e.getHeartbeatAt(),e.getAttemptCount());}}
